#include <iostream>

int main() {
    int score = 50;
    int& alias = score;  // another name for score
    int copy = score;    // its own int, starts at 50

    alias += 10;  // changes score
    copy += 5;    // changes only copy
    std::cout << score << ' ' << alias << ' ' << copy << '\n';

    auto other = alias;  // auto drops the &: other is a new int
    other += 1;
    std::cout << score << ' ' << other << '\n';

    auto& same = alias;  // same refers to score too
    same += 1;
    std::cout << score << '\n';

    int bonus = 99;
    alias = bonus;  // no re-binding: copies 99 into score
    std::cout << score << ' ' << bonus << '\n';
    return 0;
}

