#include <iostream>

void doubleCopy(int n) {
    n *= 2;
}

void doubleIt(int& n) {
    n *= 2;
}

void splitTime(int totalSeconds, int& minutes, int& seconds) {
    minutes = totalSeconds / 60;
    seconds = totalSeconds % 60;
}

int main() {
    int value = 21;
    doubleCopy(value);
    std::cout << value << '\n';
    doubleIt(value);
    std::cout << value << '\n';

    int minutes = 0;
    int seconds = 0;
    splitTime(754, minutes, seconds);
    std::cout << minutes << " min " << seconds << " s" << '\n';
    return 0;
}

