#include <iostream>
#include <string>
#include <vector>

int total(const std::vector<int>& values) {
    int sum = 0;
    for (int v : values) {
        sum += v;
    }
    // values.push_back(1); would not compile: values is const
    return sum;
}

void addName(std::vector<std::string>& names, const std::string& name) {
    names.push_back(name);  // & because it changes the caller's vector
}

void printAll(const std::vector<std::string>& names) {
    for (const auto& name : names) {
        std::cout << name << '\n';
    }
}

int main() {
    const std::vector<int> scores = {70, 85, 90, 64};
    std::vector<std::string> team = {"Ada", "Linus", "Grace"};
    std::cout << total(scores) << '\n';
    addName(team, "Mia");
    printAll(team);
    return 0;
}

