#include <cstddef>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

double average(const std::vector<double>& xs) {
    if (xs.empty()) {
        return 0.0;
    }
    double sum = 0.0;
    for (double x : xs) {
        sum += x;
    }
    return sum / static_cast<double>(xs.size());
}

int countLonger(const std::vector<std::string>& words, std::size_t minLength) {
    int count = 0;
    for (const auto& word : words) {
        if (word.size() > minLength) {
            ++count;
        }
    }
    return count;
}

void addWord(std::vector<std::string>& words, const std::string& word) {
    words.push_back(word);
}

int main() {
    std::cout << std::fixed << std::setprecision(2);
    const std::vector<double> ratings = {3.5, 4.0, 2.25, 5.0};
    std::vector<std::string> words = {"pear", "banana", "fig", "cherry", "kiwi"};
    std::cout << "Average: " << average(ratings) << '\n';
    std::cout << "Longer than 4: " << countLonger(words, 4) << '\n';
    addWord(words, "papaya");
    std::cout << "Longer than 4: " << countLonger(words, 4) << '\n';
    return 0;
}
